def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    total_opp_d = opp.count('D')
    total_my_d = me.count('D')

    if n <= 2:
        if opp[-1] == 'D':
            return 'D'
        return 'C'

    last_my = me[-1]
    last_opp = opp[-1]

    if total_opp_d == n:
        return 'D'

    recent8 = opp[-8:]
    if recent8.count('D') >= 6 and last_my == 'C':
        return 'D'

    if n >= 20 and total_opp_d * 10 >= n * 9:
        return 'D'

    if (
        100 - n > 4
        and last_my == 'D'
        and last_opp == 'C'
        and total_my_d == 1
        and total_opp_d <= 3
    ):
        return 'C'

    mutual = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'D' and opp[i] == 'D':
            mutual += 1
        else:
            break

    if mutual >= 2 and total_opp_d <= n * 0.55 and total_my_d <= n * 0.55:
        if rng.random() < 0.35:
            return 'C'

    if total_opp_d == 0 and total_my_d == 0:
        if n < 25:
            return 'C'
        return 'D'

    cnt = [0.0, 0.0, 0.0, 0.0]
    coop = [0.0, 0.0, 0.0, 0.0]
    cnt_myC = 0.0
    coop_myC = 0.0
    cnt_myD = 0.0
    coop_myD = 0.0

    for i in range(1, n):
        pm = me[i - 1]
        po = opp[i - 1]
        to = opp[i]

        s = 0
        if pm == 'D':
            s += 2
        if po == 'D':
            s += 1

        age = n - 1 - i
        if age < 4:
            w = 5.0
        elif age < 8:
            w = 2.0
        elif age < 20:
            w = 0.5
        else:
            w = 0.1

        cnt[s] += w
        if to == 'C':
            coop[s] += w

        if pm == 'C':
            cnt_myC += w
            if to == 'C':
                coop_myC += w
        else:
            cnt_myD += w
            if to == 'C':
                coop_myD += w

    base_c = (n - total_opp_d) / float(n)

    if base_c > 0.90:
        prior_c = 0.95
        prior_d = 0.52
    elif base_c > 0.75:
        prior_c = 0.88
        prior_d = 0.45
    elif base_c > 0.55:
        prior_c = 0.75
        prior_d = 0.35
    elif base_c > 0.35:
        prior_c = 0.58
        prior_d = 0.25
    elif base_c > 0.15:
        prior_c = 0.40
        prior_d = 0.15
    else:
        prior_c = 0.22
        prior_d = 0.08

    alpha = 3.0

    pc2 = (coop_myC + prior_c * alpha) / (cnt_myC + alpha)
    pd2 = (coop_myD + prior_d * alpha) / (cnt_myD + alpha)

    p0 = (coop[0] + pc2 * alpha) / (cnt[0] + alpha)
    p1 = (coop[1] + pc2 * 0.95 * alpha) / (cnt[1] + alpha)
    p2 = (coop[2] + pd2 * alpha) / (cnt[2] + alpha)
    p3 = (coop[3] + pd2 * 0.7 * alpha) / (cnt[3] + alpha)

    p = [p0, p1, p2, p3]

    for i in range(4):
        if p[i] < 0.02:
            p[i] = 0.02
        elif p[i] > 0.98:
            p[i] = 0.98

    cs = 0
    if last_my == 'D':
        cs += 2
    if last_opp == 'D':
        cs += 1

    t = 100 - n
    v = [0.0, 0.0, 0.0, 0.0]
    choice = [0, 0, 0, 0]

    for _ in range(t):
        newv = [0.0, 0.0, 0.0, 0.0]
        newchoice = [0, 0, 0, 0]

        for s in range(4):
            pc = p[s]
            imm_c = 3.0 * pc
            imm_d = 1.0 + 4.0 * pc

            val_c = imm_c + pc * v[0] + (1.0 - pc) * v[1]
            val_d = imm_d + pc * v[2] + (1.0 - pc) * v[3]

            if val_d > val_c + 0.000000000001:
                newv[s] = val_d
                newchoice[s] = 1
            else:
                newv[s] = val_c
                newchoice[s] = 0

        v = newv
        choice = newchoice

    if choice[cs] == 1:
        return 'D'
    return 'C'
